@startuml

class Aircraft {
  + name: string
  + type: string
  + yearOfManufacture: int
  + nextInspectionDate: date
}

class PassengerAircraft extends Aircraft {
  + numberOfSeats: int
}

class SeatCategory {
  + designation: string
  + offersEntertainment: boolean
  + numberOfSeats: int
}

class Passenger {
  + name: string
  + passportNumber: string
}

class Ticket {
  + ticketNumber: string
  + price: float
  + upgradeDesired: boolean
}

class Flight {
  + flightNumber: string
  + date: date
}

class Airline {
  + name: string
}

class FlightAttendant {
  + name: string
  + employmentDate: date
  + isChiefStewardess: boolean
}

class Pilot {
  + name: string
  + employmentDate: date
  + license: string
}

class Airport {
  + name: string
  + address: string
  + numberOfRunways: int
}

Aircraft "0..*" -- "0..1" Airline : belongs to
Aircraft "0..*" -- "0..1" Airport : home airport
PassengerAircraft "1" -- "*" SeatCategory : has
Passenger "1..*" -- "*" Flight : takes part in
Passenger "1" -- "*" Ticket : holds
Flight "1" -- "*" Ticket : issues
SeatCategory "1" -- "*" Ticket : assigned to
Flight "1" -- "*" FlightAttendant : employs
Flight "1" -- "1" Pilot : captained by
Flight "1" -- "1..2" Pilot : co-piloted by
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives at
Airline "1" -- "*" FlightAttendant : employs
Airline "1" -- "*" Pilot : employs
Flight "*" -- "*" Aircraft : performs

@enduml

